//! The Slint UI compiled from `ui/app.slint` (fluent style, software renderer only; ADR 0001):
//! `Flyout`, `HoverCard`, `SettingsWindow`, `AboutWindow`, the `Theme` global (one instance per
//! window: set it on each) and the structs of flyout-spec §11 and readout-spec §8.
//!
//! The generated items are not documented by Slint, hence the `missing_docs` allowance.
#![allow(missing_docs, reason = "generated by slint-build")]
#![allow(
    clippy::all,
    unused_qualifications,
    reason = "generated by slint-build"
)]

slint::include_modules!();
